/** Returns the message to show for a value, or null when the value is fine. Synchronous. */
export type Validator<V> = (value: V, values: Record<string, unknown>) => string | null;

export interface Form {
  readonly values: Record<string, unknown>;
  /** The message each field's validator left when it last ran; null for a field that is fine. */
  readonly errors: Record<string, string | null>;
  /** Stores the field's validator and runs it at once on the current value. */
  setValidator<V>(field: string, validator: Validator<V>): void;
  /** Sets the field's value and runs that field's validator. */
  set(field: string, value: unknown): void;
  /** Runs the field's validator again on its current value. */
  validate(field: string): void;
  /**
   * Calls the handler with the values unless a field has an error.
   * Does not run the validators: it reads the errors they left when they last ran.
   */
  submit<R>(handler: (values: Record<string, unknown>) => R): { ok: true; result: R } | { ok: false; errors: Record<string, string> };
}

export function createForm(initial: Record<string, unknown>): Form;
